		public CusHAWBLookups Lookups
		{
			get
			{
				if (fLookups == null || !IsLookupsCachedInBase)
				{
					fLookups = GetNewLookups();
				}

				return fLookups;
			}
		}

		protected virtual CusHAWBLookups GetNewLookups()
		{
			return new CusHAWBLookups(this);
		}

